"""The 9-line DO NOT EDIT banner hecatron puts on every file it generates.

Projects embed the same banner in their own generated files with
`hecatron banner` rather than importing this module.
"""

from __future__ import annotations


_INNER_WIDTH = 62


def make_banner(
    body: list[str],
    line_prefix: str = "# ",
    line_suffix: str = "",
) -> str:
    """Return a 9-line box-frame DO NOT EDIT banner.

    *body* must be exactly 5 lines (content rows between the title
    separator and the bottom border).  Empty strings become blank rows.
    Each output line is wrapped with *line_prefix* / *line_suffix*.
    """
    def _line(content: str) -> str:
        return f"{line_prefix}{content}{line_suffix}\n"

    top    = "\u2554" + "\u2550" * _INNER_WIDTH + "\u2557"
    mid    = "\u2560" + "\u2550" * _INNER_WIDTH + "\u2563"
    bottom = "\u255a" + "\u2550" * _INNER_WIDTH + "\u255d"

    def _row(text: str) -> str:
        return "\u2551" + text.center(_INNER_WIDTH) + "\u2551"

    def _lrow(text: str) -> str:
        return "\u2551" + " " + text.ljust(_INNER_WIDTH - 2) + " \u2551"

    return (
        _line(top)
        + _line(_row("DO NOT EDIT THIS FILE"))
        + _line(mid)
        + "".join(_line(_lrow(row)) for row in body)
        + _line(bottom)
    )


def make_header(generator_path: str, line_prefix: str = "// ", line_suffix: str = "") -> str:
    """Return a 9-line box-frame banner for a codegen-generated file."""
    return make_banner(
        [
            "This file is auto-generated by:",
            f"  {generator_path}",
            "",
            "Changes will be overwritten the next time codegen runs.",
            "Edit the generator or locale JSON instead.",
        ],
        line_prefix=line_prefix,
        line_suffix=line_suffix,
    )
